PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS instruments (id INTEGER PRIMARY KEY, symbol TEXT NOT NULL, exchange TEXT NOT NULL DEFAULT '', name TEXT NOT NULL, asset_type TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', region TEXT, timezone TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(symbol,exchange));
CREATE TABLE IF NOT EXISTS price_bars (instrument_id INTEGER NOT NULL REFERENCES instruments(id), timeframe TEXT NOT NULL, timestamp_utc TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL, close REAL NOT NULL, volume REAL, adjusted_close REAL, source TEXT NOT NULL, fetched_at_utc TEXT NOT NULL, PRIMARY KEY(instrument_id,timeframe,timestamp_utc,source));
CREATE INDEX IF NOT EXISTS idx_bars_lookup ON price_bars(instrument_id,timeframe,timestamp_utc DESC);
CREATE TABLE IF NOT EXISTS fundamentals (instrument_id INTEGER NOT NULL REFERENCES instruments(id), as_of_date TEXT NOT NULL, market_cap REAL, pe_ttm REAL, forward_pe REAL, eps_ttm REAL, revenue_ttm REAL, source TEXT NOT NULL, fetched_at_utc TEXT NOT NULL, PRIMARY KEY(instrument_id,as_of_date,source));
CREATE TABLE IF NOT EXISTS news_events (id INTEGER PRIMARY KEY, instrument_id INTEGER REFERENCES instruments(id), headline TEXT NOT NULL, url TEXT NOT NULL, publisher TEXT, published_at_utc TEXT, source TEXT NOT NULL, fetched_at_utc TEXT NOT NULL, UNIQUE(url,source));
CREATE TABLE IF NOT EXISTS watchlists (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at_utc TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS watchlist_items (watchlist_id INTEGER NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE, instrument_id INTEGER NOT NULL REFERENCES instruments(id), added_at_utc TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(watchlist_id,instrument_id));
CREATE TABLE IF NOT EXISTS indicator_presets (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, config_json TEXT NOT NULL CHECK(json_valid(config_json)), is_default INTEGER NOT NULL DEFAULT 0, updated_at_utc TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL CHECK(json_valid(value_json)), updated_at_utc TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS data_sources (code TEXT PRIMARY KEY, name TEXT NOT NULL, terms_url TEXT, display_permitted INTEGER NOT NULL DEFAULT 0, notes TEXT);
CREATE TABLE IF NOT EXISTS fetch_log (id INTEGER PRIMARY KEY, source_code TEXT REFERENCES data_sources(code), dataset TEXT NOT NULL, status TEXT NOT NULL, fetched_at_utc TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, message TEXT);
